// Lời kể được biên soạn mới từ truyện dân gian/ngụ ngôn thuộc phạm vi công cộng.
window.STORIES = [
{id:'rua-tho',title:'Rùa và Thỏ',category:'Ngụ ngôn',age:3,minutes:3,animal:'rabbit',friend:'turtle',color:'#e8edd4',tag:'Sự kiên trì',desc:'Từng bước nhỏ cũng đưa mình đến một đích thật xa.',moral:'Mỗi bạn có một thế mạnh. Kiên trì làm từng chút, không chê bai và không chủ quan sẽ giúp chúng mình tiến bộ.',scenes:[['Một lời thách đố','Thỏ chạy nhanh nhất khu rừng và thường trêu Rùa đi chậm. Rùa không giận. Một hôm, Rùa nhẹ nhàng rủ Thỏ cùng chạy tới cây sồi cuối con đường. Thỏ cười rồi đồng ý.'],['Cuộc đua bắt đầu','Cú mèo vừa hô bắt đầu, Thỏ đã lao đi như gió. Rùa chậm rãi bước theo. Thỏ ngoái lại, thấy bạn còn xa nên nghĩ: Mình nghỉ dưới bóng cây một lát cũng chẳng sao!'],['Những bước chân nhỏ','Thỏ nằm xuống rồi ngủ quên. Rùa vẫn đi đều, vượt qua viên đá, qua bụi hoa, rồi qua chỗ Thỏ đang ngủ. Mệt thì Rùa thở chậm, sau đó lại tiếp tục.'],['Niềm vui ở đích đến','Khi Thỏ tỉnh giấc, Rùa đã gần tới cây sồi. Thỏ chạy hết sức nhưng Rùa chạm đích trước. Thỏ xin lỗi vì đã chê bạn. Rùa mỉm cười: Chúng mình cùng cố gắng nhé!']],quiz:[['Vì sao Thỏ dừng lại giữa đường?',['Thỏ chủ quan và ngủ quên','Thỏ bị lạc','Thỏ đã về đích'],0],['Điều gì giúp Rùa về đích trước?',['Một chiếc xe','Sự kiên trì','Một đôi cánh'],1],['Khi bạn làm chậm hơn mình, bé nên làm gì?',['Chê bạn','Không chơi với bạn','Động viên và tôn trọng bạn'],2]]},
{id:'kien-bo-cau',title:'Kiến và Chim Bồ Câu',category:'Tình bạn',age:3,minutes:3,animal:'bird',friend:'ant',color:'#e2edf0',tag:'Biết giúp đỡ',desc:'Một chiếc lá nhỏ mở đầu cho một tình bạn thật lớn.',moral:'Ai cũng có thể giúp người khác theo cách của mình. Hãy biết cảm ơn và tìm người lớn hỗ trợ nếu tình huống nguy hiểm.',scenes:[['Bên dòng suối','Một chú Kiến ra suối tìm nước uống. Bờ đất ướt khiến chú trượt chân xuống dòng nước. Kiến cố bám vào một cọng cỏ nhưng nước cứ đưa chú ra xa.'],['Chiếc lá cứu bạn','Bồ Câu trên cành cây nhìn thấy Kiến đang chới với. Cô thả một chiếc lá xuống bên cạnh. Kiến trèo lên lá và theo dòng nước trôi vào bờ. Chú vẫy râu cảm ơn cô bạn tốt bụng.'],['Một việc bất ngờ','Vài hôm sau, có người giăng lưới gần chỗ Bồ Câu đang đậu. Kiến thấy vậy liền chạy đến đốt vào chân người ấy. Người giăng lưới giật mình kêu lên, làm Bồ Câu chú ý.'],['Đôi bạn của khu rừng','Bồ Câu vỗ cánh bay khỏi chiếc lưới. Cô trở lại cảm ơn Kiến. Chú Kiến bé xíu cũng có thể giúp bạn! Từ đó, hai bạn luôn quan tâm đến nhau bên dòng suối nhỏ.']],quiz:[['Bồ Câu thả gì xuống cứu Kiến?',['Viên đá','Chiếc lá','Cành cây khô'],1],['Kiến đã làm gì để báo động?',['Đốt vào chân người giăng lưới','Đi ngủ','Trốn vào tổ'],0],['Khi được giúp đỡ, bé nên nói gì?',['Không nói gì','Đi chỗ khác','Cảm ơn bạn'],2]]},
{id:'bo-dua',title:'Câu Chuyện Bó Đũa',category:'Cổ tích',age:6,minutes:4,animal:'bear',friend:'bird',color:'#f2e6d4',tag:'Yêu thương gia đình',desc:'Bài học giản dị của người cha từ những chiếc đũa.',moral:'Gia đình mạnh mẽ hơn khi mọi người biết lắng nghe, nhường nhịn và cùng giải quyết khó khăn.',scenes:[['Người cha lo lắng','Trong một gia đình nọ, những người con thường tranh cãi vì chuyện nhỏ. Người cha buồn lắm. Ông muốn các con hiểu rằng sự hòa thuận quý hơn việc lúc nào cũng giành phần đúng.'],['Thử bẻ bó đũa','Một buổi sáng, cha đặt bó đũa lên bàn và mời từng người bẻ thử. Người anh gắng sức, người em cũng thử, nhưng bó đũa vẫn nguyên vẹn. Ai nấy nhìn nhau ngạc nhiên.'],['Từng chiếc một','Cha tháo sợi dây buộc rồi bẻ từng chiếc đũa. Lần này việc ấy thật dễ dàng. Ông nói: Khi đứng riêng lẻ, chúng ta dễ gặp khó. Khi cùng nhau, chúng ta có thêm sức mạnh.'],['Một mái nhà ấm áp','Những người con hiểu ý cha. Họ nói lời xin lỗi và cùng sửa lại hàng rào trong vườn. Công việc xong nhanh hơn, tiếng cười cũng trở về. Từ đó, họ cố gắng lắng nghe nhau nhiều hơn.']],quiz:[['Những người con có bẻ gãy cả bó đũa không?',['Không','Có ngay lập tức','Chưa ai thử'],0],['Cha bẻ đũa bằng cách nào?',['Dùng một hòn đá','Bẻ từng chiếc','Nhờ gió thổi'],1],['Câu chuyện nhắc chúng mình điều gì?',['Luôn tranh phần thắng','Làm mọi việc một mình','Yêu thương và đoàn kết'],2]]},
{id:'cao-nho',title:'Cáo và Chùm Nho',category:'Ngụ ngôn',age:6,minutes:2,animal:'fox',friend:'bird',color:'#eee3ec',tag:'Sự trung thực',desc:'Chùm nho ở quá cao, còn lời nói thật ở rất gần.',moral:'Chưa làm được một việc không có nghĩa việc ấy không tốt. Mình có thể thừa nhận khó khăn, thử cách khác hoặc nhờ giúp đỡ.',scenes:[['Giàn nho tím','Cáo đi qua khu vườn và thấy những chùm nho tím mọng dưới tán lá. Trời nắng, Cáo vừa đói vừa khát. Chú ngước nhìn giàn nho cao và muốn hái một chùm.'],['Nhảy lên nào','Cáo nhún chân nhảy, rồi nhảy thêm lần nữa. Nhưng chùm nho vẫn ở quá cao. Sau nhiều lần thử, Cáo ngồi xuống thở. Chú chưa nghĩ ra một cách khác để hái nho.'],['Một lời chê vội','Không lấy được nho, Cáo quay đi và nói: Chắc nho ấy chua lắm, mình chẳng thích đâu! Chim Sẻ ở gần đó nghiêng đầu: Cậu chưa nếm, sao biết nho chua nhỉ?'],['Dám nói điều thật','Cáo dừng lại, ngượng ngùng đáp: Thật ra mình chưa với tới được. Chim Sẻ gật đầu. Thừa nhận mình chưa làm được cũng cần can đảm, phải không nào?']],quiz:[['Cáo muốn lấy thứ gì?',['Củ cà rốt','Chùm nho','Quả táo'],1],['Vì sao Cáo chưa hái được nho?',['Nho ở quá cao','Nho bị giấu','Cáo không nhìn thấy'],0],['Chưa làm được việc gì, bé có thể làm gì?',['Chê việc ấy ngay','Giận mọi người','Thử cách khác hoặc nhờ giúp'],2]]},
{id:'doi-ban',title:'Đôi Bạn Nhỏ',category:'Tình bạn',age:3,minutes:3,animal:'duck',friend:'chick',color:'#e9edce',tag:'Quan tâm bạn bè',desc:'Gà con và Vịt con có những tài năng rất khác nhau.',moral:'Bạn bè có những khả năng khác nhau. Biết quan tâm và giúp đỡ sẽ làm tình bạn đẹp hơn. Trẻ nhỏ chỉ chơi gần nước khi có người lớn trông coi.',scenes:[['Buổi sáng trong vườn','Gà con và Vịt con chơi ở khu vườn bên ao. Gà mẹ ở gần đó chăm luống rau. Gà con bới đất rất giỏi, còn Vịt con có thể bơi nhẹ nhàng trên mặt nước.'],['Một tiếng gọi','Khi Gà mẹ quay vào lấy giỏ, Cáo bất ngờ xuất hiện sau bụi cây. Gà con sợ quá gọi bạn. Vịt con bơi sát bờ, đón Gà lên lưng và đưa ra chỗ Cáo không với tới.'],['Mọi người đã an toàn','Gà mẹ nghe tiếng liền chạy đến gọi người giúp. Cáo bỏ đi. Gà con và Vịt con trở lại bờ cùng mẹ. Hai bạn cảm ơn nhau rồi ngồi nghỉ dưới bóng cây.'],['Bạn cũng giỏi mà','Trên đường về, chân Vịt vướng một sợi dây leo. Gà dùng mỏ gỡ dây cho bạn. Vịt vui vẻ nói: Cậu cũng giúp tớ được đấy! Mỗi bạn một tài, cùng nhau thật vui.']],quiz:[['Bạn nào bơi giỏi?',['Gà con','Vịt con','Cả hai đều không biết'],1],['Gà đã giúp Vịt việc gì?',['Gỡ dây leo vướng chân','Dạy bay','Xây một ngôi nhà'],0],['Khi chơi gần ao hồ, bé cần gì?',['Tự đi một mình','Nhảy xuống thử','Người lớn trông coi'],2]]},
{id:'su-tu-chuot',title:'Sư Tử và Chuột Nhắt',category:'Ngụ ngôn',age:3,minutes:3,animal:'lion',friend:'mouse',color:'#f0e8c9',tag:'Lòng tốt',desc:'Một người bạn bé xíu cũng có thể làm điều phi thường.',moral:'Đừng đánh giá bạn chỉ qua vẻ ngoài. Một hành động tử tế có thể mở đầu cho nhiều điều tốt đẹp.',scenes:[['Giấc ngủ của Sư Tử','Sư Tử đang ngủ dưới tán cây. Chuột Nhắt chạy qua, vô tình làm cành lá động đậy khiến Sư Tử thức giấc. Chuột vội xin lỗi và mong được trở về nhà.'],['Một lời hứa nhỏ','Sư Tử thấy Chuột lễ phép nên để bạn đi. Chuột cảm ơn rồi nói: Có dịp, tôi sẽ giúp bác! Sư Tử mỉm cười, chưa biết người bạn nhỏ ấy có thể giúp mình bằng cách nào.'],['Chiếc lưới trong rừng','Một hôm, Sư Tử mắc vào tấm lưới bị bỏ trong rừng. Càng vùng vẫy, dây càng siết. Nghe tiếng gọi, Chuột Nhắt chạy tới. Bạn bình tĩnh tìm những nút dây sát mặt đất.'],['Hàm răng bé mà giỏi','Chuột kiên nhẫn cắn đứt từng sợi dây. Cuối cùng, tấm lưới bung ra và Sư Tử bước được ra ngoài. Sư Tử cúi đầu cảm ơn: Bạn nhỏ của tôi, việc bạn làm thật lớn lao!']],quiz:[['Ai mắc vào chiếc lưới?',['Sư Tử','Chuột Nhắt','Chim Sẻ'],0],['Chuột giúp bạn bằng cách nào?',['Thổi bay lưới','Cắn đứt dây lưới','Đẩy một tảng đá'],1],['Có nên coi thường bạn nhỏ bé không?',['Có','Chỉ khi mình khỏe','Không, ai cũng có điểm mạnh'],2]]},
{id:'qua-nuoc',title:'Quạ và Chiếc Bình Nước',category:'Ngụ ngôn',age:6,minutes:3,animal:'crow',friend:'bird',color:'#dce8e4',tag:'Trí thông minh',desc:'Một ý tưởng nhỏ làm mực nước dâng lên từng chút.',moral:'Khi gặp khó khăn, hãy bình tĩnh quan sát và thử những cách phù hợp. Kiên nhẫn giúp ý tưởng trở thành kết quả.',scenes:[['Ngày nắng nóng','Quạ bay qua cánh đồng trong buổi trưa nắng. Tìm mãi, bạn mới thấy một chiếc bình có chút nước dưới đáy. Quạ vui lắm, vội đậu xuống bên cạnh.'],['Chiếc cổ bình dài','Mỏ Quạ không chạm được tới nước vì cổ bình dài và hẹp. Bình lại nặng, bạn không thể nghiêng được. Quạ ngừng lại, nhìn quanh thay vì cố làm chiếc bình đổ.'],['Những viên sỏi sạch','Bên cạnh có những viên sỏi nhỏ. Quạ thả thử một viên vào bình. Nước nhích lên một chút! Quạ tiếp tục nhặt từng viên sỏi và thả vào, rất cẩn thận.'],['Một ngụm nước mát','Mực nước dâng tới chỗ mỏ Quạ có thể chạm. Quạ uống nước rồi nghỉ dưới bóng cây. Nhờ quan sát và kiên nhẫn, bạn đã tìm được cách giải quyết việc khó.']],quiz:[['Vì sao Quạ không uống được nước lúc đầu?',['Nước quá nóng','Nước ở quá thấp','Không có bình'],1],['Quạ thả gì vào bình?',['Những viên sỏi','Lá khô','Hạt thóc'],0],['Khi gặp việc khó, mình nên làm gì?',['Đập vỡ đồ vật','Bỏ ngay lập tức','Bình tĩnh quan sát, tìm cách'],2]]},
{id:'gio-mat-troi',title:'Gió và Mặt Trời',category:'Ngụ ngôn',age:6,minutes:3,animal:'bear',friend:'bird',color:'#f2e6cb',tag:'Sự dịu dàng',desc:'Sức mạnh đôi khi đến từ những điều thật ấm áp.',moral:'Sự dịu dàng và thấu hiểu thường hiệu quả hơn ép buộc. Hãy thử nói chuyện nhẹ nhàng để người khác cảm thấy an tâm.',scenes:[['Ai mạnh hơn?','Gió và Mặt Trời tranh luận xem ai mạnh hơn. Nhìn thấy một người đang đi trên đường, họ cùng thử xem ai khiến người ấy tự cởi chiếc áo khoác trước.'],['Gió thổi thật mạnh','Gió thổi ào ào. Cây nghiêng, bụi bay, chiếc áo của người đi đường phấp phới. Nhưng trời càng lạnh, người ấy càng kéo áo sát vào mình và giữ thật chặt.'],['Ánh nắng dịu êm','Đến lượt Mặt Trời. Không ồn ào, Mặt Trời tỏa những tia nắng ấm. Gió lặng xuống, con đường dễ đi hơn. Người đi đường cảm thấy thoải mái và bước chậm lại.'],['Một bài học ấm áp','Khi thấy đủ ấm, người ấy tự cởi áo khoác và ngồi nghỉ dưới cây. Gió hiểu ra: Không phải cứ làm thật mạnh là sẽ được việc. Dịu dàng cũng là một sức mạnh.']],quiz:[['Gió thổi mạnh khiến người đi đường làm gì?',['Giữ chặt áo hơn','Cởi áo ngay','Chạy về biển'],0],['Ai khiến người ấy tự cởi áo?',['Gió','Mặt Trời','Mặt Trăng'],1],['Cách cư xử nào được nhắc đến?',['Ép bạn làm theo','Quát thật to','Nhẹ nhàng và thấu hiểu'],2]]},
{id:'ba-chu-heo',title:'Ba Chú Heo Con',category:'Cổ tích',age:3,minutes:4,animal:'pig',friend:'pig',color:'#f0dfdb',tag:'Sự chuẩn bị',desc:'Một ngôi nhà vững chãi cần thời gian và sự chăm chút.',moral:'Làm cẩn thận và biết chuẩn bị giúp chúng mình an toàn hơn. Khi gặp nguy hiểm, hãy tìm nơi an toàn và gọi người lớn giúp đỡ.',scenes:[['Ba ngôi nhà','Ba chú Heo muốn làm nhà. Heo Cả chọn rơm để xây cho nhanh. Heo Hai dùng cành cây. Heo Út dành nhiều ngày xếp từng viên gạch, làm nền và cánh cửa thật chắc.'],['Vị khách không mời','Sói đến gõ cửa nhà rơm. Heo Cả không mở, nhưng Sói thổi mạnh khiến rơm bay tung. Heo Cả chạy sang nhà gỗ của anh em. Cả hai vẫn chưa thấy yên tâm.'],['Cùng tới nhà gạch','Sói thổi tiếp làm những cành cây rơi xuống. Hai chú Heo nhanh chóng chạy tới nhà gạch. Heo Út đón hai anh vào, khóa cửa và gọi hàng xóm tới giúp.'],['Mái ấm vững vàng','Sói thổi mãi mà tường gạch không lay chuyển. Nghe tiếng hàng xóm đến, Sói bỏ đi. Ba anh em ôm nhau rồi cùng dựng lại những ngôi nhà chắc chắn. Việc cẩn thận thật đáng công!']],quiz:[['Heo Út xây nhà bằng gì?',['Rơm','Gạch','Lá cây'],1],['Khi gặp Sói, các chú Heo tìm đến đâu?',['Nhà gạch an toàn','Giữa khu rừng','Bờ suối'],0],['Câu chuyện khuyên mình điều gì?',['Làm thật vội','Không cần chuẩn bị','Làm cẩn thận, biết nhờ giúp'],2]]},
{id:'hat-mam',title:'Hạt Mầm Bé Xíu',category:'Trước giờ ngủ',age:3,minutes:3,animal:'rabbit',friend:'bird',color:'#e6ead8',tag:'Kiên nhẫn lớn lên',desc:'Một câu chuyện mới về những điều đang lớn lên âm thầm.',moral:'Mỗi người lớn lên theo nhịp riêng. Hãy chăm sóc bản thân và kiên nhẫn với những điều mình đang học.',scenes:[['Trong lòng đất','Một hạt mầm nằm yên trong đất mềm. Bên trên, khu vườn đã có nhiều bông hoa. Hạt mầm nghĩ: Bao giờ mình mới được nhìn thấy bầu trời nhỉ? Đất dịu dàng ôm lấy bạn.'],['Cơn mưa nhỏ','Đêm ấy, mưa gõ những tiếng tí tách. Hạt mầm uống từng giọt nước và cảm thấy mình thay đổi. Một chiếc rễ bé xíu bắt đầu mọc ra. Bạn vẫn chưa thấy mặt trời, nhưng bạn đang lớn.'],['Một chiếc lá đầu tiên','Sáng nọ, mầm xanh nhú khỏi mặt đất. Bạn gặp Thỏ đang tưới vườn. Thỏ reo: Chào chiếc lá nhỏ! Hạt mầm nhìn xung quanh. Bầu trời rộng và xanh hơn cả điều bạn tưởng tượng.'],['Ngủ ngoan nhé','Chiều xuống, chiếc lá khép nhẹ trong gió. Mầm biết ngày mai mình sẽ lớn thêm một chút. Không cần vội. Trong khu vườn yên ả, bạn ngủ ngon dưới ánh trăng dịu dàng.']],quiz:[['Hạt mầm nằm ở đâu lúc đầu?',['Trong lòng đất','Trên đám mây','Trong chiếc cốc khô'],0],['Điều gì giúp hạt mầm có nước?',['Tiếng hát','Cơn mưa','Ánh trăng'],1],['Mỗi người có lớn lên giống hệt nhau không?',['Luôn giống hệt','Phải nhanh nhất','Không, mỗi người có nhịp riêng'],2]]},
{id:'tho-trang',title:'Thỏ Con Chào Mặt Trăng',category:'Trước giờ ngủ',age:3,minutes:3,animal:'rabbit',friend:'mouse',color:'#dfe3ee',tag:'Thói quen buổi tối',desc:'Chào một ngày thật vui, đón một giấc mơ thật hiền.',moral:'Một thói quen buổi tối nhẹ nhàng giúp mình thư giãn: cất đồ chơi, vệ sinh cá nhân và dành thời gian ấm áp bên gia đình.',scenes:[['Khu vườn lên đèn','Mặt trời đi ngủ sau ngọn đồi. Thỏ Con vẫn muốn chơi thêm. Mẹ chỉ lên bầu trời: Con nhìn xem, Mặt Trăng đã tới rồi. Chúng mình cùng chào buổi tối nhé.'],['Tạm biệt đồ chơi','Thỏ đặt từng khối gỗ vào giỏ, xếp sách lên kệ. Cảm ơn các bạn vì một ngày vui! Căn phòng gọn gàng hơn. Thỏ cũng thấy lòng mình yên hơn một chút.'],['Một lời cảm ơn','Đánh răng và rửa mặt xong, Thỏ nép bên mẹ. Hôm nay con thích nhất lúc tưới cây cùng mẹ. Mẹ ôm Thỏ: Mẹ cũng rất vui vì có con ở bên.'],['Chào nhé, Mặt Trăng','Thỏ kéo chăn lên, nhìn vầng trăng ngoài cửa sổ. Gió khẽ đưa lá, căn nhà thật ấm. Thỏ thì thầm chúc mọi người ngủ ngon rồi nhắm mắt, mang theo một nụ cười nhỏ.']],quiz:[['Trước khi ngủ, Thỏ cất gì?',['Đồ chơi và sách','Những đám mây','Mặt Trăng'],0],['Thỏ làm gì sau khi cất đồ chơi?',['Ra vườn một mình','Đánh răng, rửa mặt','Chạy nhảy thật lâu'],1],['Một việc nhẹ nhàng trước giờ ngủ là gì?',['La hét thật to','Chơi mãi không nghỉ','Nghe truyện bên người thân'],2]]},
{id:'ban-gau',title:'Gấu Con Biết Xin Lỗi',category:'Tình bạn',age:3,minutes:3,animal:'bear',friend:'rabbit',color:'#eadfce',tag:'Biết nhận lỗi',desc:'Hai tiếng xin lỗi giúp một ngày buồn trở nên ấm áp.',moral:'Ai cũng có lúc mắc lỗi. Biết nói lời xin lỗi, lắng nghe và cùng sửa lại là cách chăm sóc tình bạn.',scenes:[['Ngọn tháp của Thỏ','Thỏ xếp một ngọn tháp bằng gỗ rất đẹp. Gấu Con ôm quả bóng chạy ngang, không để ý nên va vào tháp. Những khối gỗ đổ xuống sàn. Thỏ đứng lặng, buồn rầu.'],['Một chút ngượng ngùng','Gấu định nói: Tại tháp của cậu ở giữa đường! Nhưng nhìn thấy đôi tai Thỏ cụp xuống, Gấu biết bạn đã mất nhiều công. Gấu hít một hơi rồi đặt quả bóng xuống.'],['Hai tiếng dịu dàng','Tớ xin lỗi vì chạy vội làm đổ tháp. Tớ có thể giúp cậu xếp lại không? Thỏ gật đầu. Gấu lắng nghe bạn chỉ chỗ đặt từng khối gỗ, cẩn thận hơn lúc trước.'],['Ngọn tháp mới','Hai bạn cùng xếp được một ngọn tháp có cả chiếc cầu. Thỏ vui trở lại. Gấu nhớ từ nay sẽ chơi bóng ngoài sân. Một lời xin lỗi cùng hành động sửa sai đã giữ tình bạn thật ấm.']],quiz:[['Vì sao ngọn tháp đổ?',['Gấu chạy va vào','Trời mưa','Thỏ đem cất'],0],['Gấu đã làm gì để sửa lỗi?',['Bỏ đi','Xin lỗi và cùng xếp lại','Giấu các khối gỗ'],1],['Lỡ làm bạn buồn, mình nên làm gì?',['Đổ lỗi cho bạn','Không nói gì','Nhận lỗi và tìm cách sửa'],2]]},
// Truyện mầm non (3–5 tuổi), lời kể biên soạn mới.
{id:'cu-cai',title:'Nhổ Củ Cải Khổng Lồ',category:'Cổ tích',age:3,minutes:3,animal:'pig',friend:'mouse',color:'#eef0d2',tag:'Đoàn kết',desc:'Một mình không nhổ nổi, cùng nhau thì làm được!',moral:'Bạn nào cũng có ích, dù là bạn nhỏ nhất. Khi cùng nhau cố gắng, việc khó cũng hóa dễ.',scenes:[['Hạt giống của ông','Mùa xuân, ông trồng một hạt củ cải nhỏ. Ngày nào ông cũng tưới nước và nhổ cỏ. Củ cải lớn lên, lớn mãi, to hơn cả cái nồi trong bếp.'],['Ông kéo, kéo mãi','Đến ngày thu hoạch, ông nắm lá củ cải rồi kéo thật mạnh. Ông kéo, kéo mãi mà củ cải vẫn nằm yên. Ông gọi: Cháu ơi, ra giúp ông với!'],['Thêm một bạn nữa','Cháu ôm lưng ông, Heo Con ôm lưng cháu. Một, hai, ba, kéo! Củ cải chỉ nhúc nhích một chút. Ai cũng thở phì phò nhưng không ai bỏ cuộc.'],['Bạn Chuột tí hon','Chuột Nhắt chạy tới: Cho tớ giúp với! Mọi người lại cùng kéo, và phựt một cái, củ cải bật lên. Cả nhà reo vui và nấu một nồi canh thật ngon.']],quiz:[['Ông trồng cây gì?',['Cây cà rốt','Củ cải','Cây ngô'],1],['Ai là bạn đến giúp sau cùng?',['Chuột Nhắt','Bác Gấu','Chim Sẻ'],0],['Vì sao nhổ được củ cải?',['Vì củ cải nhỏ','Vì mọi người cùng kéo','Vì trời mưa'],1]]},
{id:'tho-vang-loi',title:'Thỏ Con Không Vâng Lời',category:'Kỹ năng sống',age:3,minutes:3,animal:'rabbit',friend:'fox',color:'#e6efd8',tag:'Vâng lời mẹ',desc:'Đi chơi xa một mình, Thỏ Con đã gặp chuyện gì?',moral:'Lời dặn của bố mẹ giúp bé an toàn. Bé chơi ở nơi người lớn nhìn thấy và không đi xa một mình nhé.',scenes:[['Lời mẹ dặn','Sáng nay trời đẹp. Thỏ Mẹ dặn: Con chơi ở gần nhà thôi nhé, trong rừng có Cáo đấy. Thỏ Con gật đầu: Vâng ạ! Rồi Thỏ Con ra sân chơi.'],['Đuổi theo bướm vàng','Một chú bướm vàng bay qua. Thỏ Con chạy theo, chạy mãi, quên cả lời mẹ dặn. Khi ngẩng lên, Thỏ Con thấy mình đã vào sâu trong rừng.'],['Cáo xuất hiện','Sau bụi cây, Cáo lén lút đi ra. Thỏ Con sợ run cả người. Bác Gấu đang đi qua liền đứng chắn trước mặt Cáo. Cáo hoảng quá vội chạy mất.'],['Về với mẹ','Bác Gấu đưa Thỏ Con về nhà. Thỏ Con ôm mẹ: Con xin lỗi mẹ, từ nay con sẽ nghe lời. Thỏ Mẹ ôm con thật chặt và cảm ơn Bác Gấu.']],quiz:[['Thỏ Mẹ dặn Thỏ Con điều gì?',['Chơi gần nhà','Đi hái nấm','Đi ngủ sớm'],0],['Vì sao Thỏ Con vào sâu trong rừng?',['Đi tìm mẹ','Mải đuổi theo bướm','Đi học'],1],['Ai đã giúp Thỏ Con?',['Bạn Vịt','Bác Gấu','Chú Cáo'],1]]},
{id:'chuot-tham-an',title:'Chú Chuột Tham Ăn',category:'Thói quen tốt',age:3,minutes:3,animal:'mouse',friend:'mouse',color:'#f2e8d6',tag:'Ăn vừa đủ',desc:'Ăn nhiều quá, Chuột chui không lọt hang!',moral:'Ăn vừa đủ no giúp cơ thể khỏe mạnh. Bé ăn chậm, nhai kỹ và không tham ăn quá nhiều nhé.',scenes:[['Cái hang nhỏ','Chuột Nhắt sống trong một cái hang nhỏ dưới chân tường. Cửa hang vừa đủ để Chuột chui ra chui vào. Một đêm, Chuột ngửi thấy mùi bánh thơm phức trong bếp.'],['Ăn mãi không thôi','Chuột ăn một miếng bánh, rồi thêm miếng phô mai, rồi cả bắp ngô. Bụng đã no căng mà Chuột vẫn ăn tiếp: Ngon quá, ăn thêm chút nữa!'],['Kẹt ở cửa hang','Ăn xong, Chuột chạy về hang. Nhưng bụng to quá, Chuột chui vào không lọt! Chuột bị kẹt ở cửa hang, sợ hãi kêu chít chít.'],['Bài học của Chuột','Chuột phải đứng đợi đến sáng, bụng mới nhỏ lại và chui vào được. Từ đó, Chuột chỉ ăn vừa đủ no, phần còn lại thì cất dành cho bữa sau.']],quiz:[['Chuột ngửi thấy mùi gì trong bếp?',['Mùi bánh thơm','Mùi hoa','Mùi mưa'],0],['Vì sao Chuột không chui vào hang được?',['Cửa hang bị đóng','Bụng Chuột quá to','Chuột quên đường'],1],['Bé nên ăn như thế nào?',['Ăn thật nhiều','Ăn vừa đủ no','Không ăn gì'],1]]},
{id:'ga-trong-cao',title:'Gà Trống Đuổi Cáo',category:'Cổ tích',age:3,minutes:3,animal:'chick',friend:'rabbit',color:'#f3ead2',tag:'Dũng cảm',desc:'Ai giúp Thỏ lấy lại ngôi nhà nhỏ?',moral:'Lấy đồ của người khác là không đúng. Khi bạn gặp khó khăn, mình hãy dũng cảm và cùng nhau giúp bạn.',scenes:[['Ngôi nhà của Thỏ','Thỏ có một ngôi nhà gỗ nhỏ xinh. Một hôm Cáo đến gõ cửa: Cho tớ vào sưởi ấm một lát nhé! Thỏ tốt bụng mở cửa. Nhưng Cáo vào rồi thì đuổi Thỏ ra ngoài.'],['Bác Gấu thử giúp','Thỏ ngồi khóc bên đường. Bác Gấu đi qua liền đến gõ cửa. Cáo hét to: Ta mà ra thì các ngươi chạy cho mau! Bác Gấu giật mình, lùi lại.'],['Gà Trống đến','Gà Trống nghe chuyện liền nói: Để tớ giúp cậu! Gà Trống đứng trước cửa, vươn cổ gáy thật to: Ò ó o! Gà Trống đến đây, Cáo mau ra khỏi nhà!'],['Thỏ về nhà','Nghe tiếng gáy vang và dũng cảm, Cáo sợ quá chạy biến vào rừng. Thỏ được về nhà. Thỏ mời Gà Trống và Bác Gấu vào uống trà, ba bạn cười vui vẻ.']],quiz:[['Ai đã chiếm nhà của Thỏ?',['Cáo','Gà Trống','Bác Gấu'],0],['Gà Trống đã làm gì?',['Bỏ chạy','Gáy thật to đuổi Cáo','Ngủ quên'],1],['Bạn gặp khó khăn, bé sẽ làm gì?',['Đi chỗ khác','Cười bạn','Tìm cách giúp bạn'],2]]},
{id:'gau-chia-qua',title:'Gấu Con Chia Quà',category:'Tình bạn',age:3,minutes:3,animal:'bear',friend:'rabbit',color:'#efe3d0',tag:'Biết chia sẻ',desc:'Một giỏ táo, chia cho mọi người cùng vui.',moral:'Chia sẻ với mọi người làm niềm vui lớn hơn. Có quà ngon, bé nhớ mời bạn bè và người thân nhé.',scenes:[['Giỏ táo chín','Gấu Con vào rừng hái quả. Gấu hái được một giỏ táo đỏ thật đầy. Gấu vừa đi vừa hát: Táo ngon, táo ngọt, mang về cho cả nhà!'],['Gặp các bạn','Trên đường về, Gấu gặp Thỏ, Chuột và Chim Sẻ. Các bạn chào Gấu và nhìn giỏ táo. Gấu nghĩ: Một mình mình ăn thì buồn lắm.'],['Mỗi bạn một quả','Gấu Con lấy táo ra chia: Một quả cho Thỏ, một quả cho Chuột, một quả cho Chim Sẻ. Các bạn cùng đếm: Một, hai, ba! Ai cũng vui vẻ cảm ơn Gấu.'],['Phần quà cho mẹ','Gấu mang những quả còn lại về nhà, tặng mẹ quả to nhất. Gấu Mẹ khen: Con biết chia sẻ, mẹ vui lắm! Gấu Con thấy lòng ấm áp như ánh mặt trời.']],quiz:[['Gấu Con hái được quả gì?',['Táo đỏ','Chuối','Cam'],0],['Gấu chia táo cho mấy bạn?',['Một bạn','Ba bạn','Năm bạn'],1],['Có quà ngon, bé sẽ làm gì?',['Giấu đi ăn một mình','Mời mọi người cùng ăn','Vứt đi'],1]]},
{id:'heo-rua-tay',title:'Heo Con Rửa Tay',category:'Thói quen tốt',age:3,minutes:3,animal:'pig',friend:'pig',color:'#f4e1dc',tag:'Giữ vệ sinh',desc:'Rửa tay sạch, ăn bánh mới ngon!',moral:'Rửa tay bằng xà phòng trước khi ăn và sau khi chơi giúp bé không bị đau bụng, luôn khỏe mạnh.',scenes:[['Vũng bùn vui vẻ','Heo Con thích chơi ở vũng bùn sau nhà. Heo nhảy lộp bộp, bùn dính đầy tay, đầy chân. Heo cười khúc khích: Vui quá, vui quá!'],['Bánh thơm của mẹ','Heo Mẹ gọi: Heo Con ơi, vào ăn bánh nào! Heo Con chạy ngay vào và định cầm bánh bằng đôi tay lấm bùn. Mẹ nhẹ nhàng nói: Khoan đã con ơi!'],['Xoa xà phòng','Mẹ dẫn Heo Con ra chậu nước. Heo làm ướt tay, xoa xà phòng thành bọt trắng, chà lòng bàn tay, mu bàn tay, từng ngón tay, rồi rửa lại thật sạch.'],['Bữa bánh ngon','Đôi tay Heo Con đã sạch thơm. Heo lau khô tay rồi ăn bánh cùng mẹ. Heo nói: Từ nay trước khi ăn, con sẽ tự rửa tay ạ!']],quiz:[['Heo Con thích chơi ở đâu?',['Vũng bùn','Trên cây','Dưới sông'],0],['Rửa tay cần có gì?',['Nước và xà phòng','Cát','Lá cây'],0],['Khi nào bé cần rửa tay?',['Chỉ khi đi ngủ','Trước khi ăn','Không cần rửa'],1]]},
{id:'gau-hai-tho',title:'Bác Gấu và Hai Chú Thỏ',category:'Tình bạn',age:3,minutes:3,animal:'bear',friend:'rabbit',color:'#e2e9ee',tag:'Lòng tốt',desc:'Trời mưa to, ai sẽ mở cửa cho Bác Gấu?',moral:'Giúp đỡ người khác khi họ cần là việc làm tốt. Lòng tốt sẽ mang lại những người bạn tốt.',scenes:[['Cơn mưa bất chợt','Bác Gấu đi chơi xa thì trời đổ mưa to. Lông Bác ướt sũng, lạnh run. Bác thấy nhà Thỏ Nâu liền gõ cửa: Cho bác trú mưa nhờ một lát nhé!'],['Cánh cửa đóng chặt','Thỏ Nâu nhìn ra rồi nói: Bác to quá, nhà cháu chật lắm! Rồi Thỏ Nâu đóng cửa lại. Bác Gấu buồn bã đi tiếp dưới mưa.'],['Nhà Thỏ Trắng','Bác Gấu gõ cửa nhà Thỏ Trắng. Thỏ Trắng vội mở cửa: Bác vào đây sưởi ấm đi ạ! Thỏ lau khô người cho Bác và mời Bác uống trà nóng.'],['Người bạn tốt','Hôm sau, gió to làm cây đổ chắn cửa nhà Thỏ Nâu. Bác Gấu khỏe mạnh đến nhấc cây đi. Thỏ Nâu xấu hổ xin lỗi. Từ đó ba bạn thân nhau.']],quiz:[['Vì sao Bác Gấu gõ cửa?',['Vì trời mưa to','Vì đói bụng','Vì đi lạc'],0],['Ai đã mở cửa cho Bác Gấu?',['Thỏ Nâu','Thỏ Trắng','Chú Cáo'],1],['Bạn gặp khó khăn, bé nên làm gì?',['Đóng cửa lại','Giúp đỡ bạn','Cười bạn'],1]]},
{id:'vit-tap-boi',title:'Vịt Con Tập Bơi',category:'Kỹ năng sống',age:3,minutes:3,animal:'duck',friend:'duck',color:'#dcecef',tag:'Dũng cảm thử',desc:'Sợ nước lắm, nhưng Vịt Con vẫn thử từng chút một.',moral:'Việc gì mới cũng làm mình hơi sợ. Bé hãy thử từng chút một, có người lớn bên cạnh, rồi bé sẽ làm được.',scenes:[['Bên bờ ao','Các anh chị vịt đã bơi tung tăng dưới ao. Chỉ có Vịt Con đứng trên bờ. Vịt Con nhìn mặt nước rồi lắc đầu: Nước sâu quá, con sợ lắm!'],['Mẹ động viên','Vịt Mẹ bơi lại gần: Con đừng sợ, có mẹ ở đây. Mình thử nhúng chân trước nhé. Vịt Con thò một chân xuống nước. Ồ, nước mát quá!'],['Từng chút một','Vịt Con bước xuống chỗ nước nông, rồi khua chân thật đều. Lúc đầu Vịt Con còn chao đảo, nhưng mẹ luôn bơi bên cạnh. Một, hai, một, hai, Vịt Con nổi lên rồi!'],['Bơi giỏi rồi','Chẳng mấy chốc, Vịt Con đã bơi theo mẹ ra giữa ao. Chim Sẻ trên cành vỗ cánh khen. Vịt Con vui sướng: Con làm được rồi! Mai con lại tập tiếp nhé mẹ!']],quiz:[['Lúc đầu Vịt Con cảm thấy thế nào?',['Sợ nước','Buồn ngủ','Đói bụng'],0],['Ai đã động viên Vịt Con?',['Vịt Mẹ','Chú Cáo','Bác Sư Tử'],0],['Khi tập việc mới, bé nên làm gì?',['Bỏ cuộc ngay','Thử từng chút một','Khóc thật to'],1]]},
// Thể loại mầm non mới: thói quen, kỹ năng sống, học đếm và màu sắc, đồng dao và thơ, thiên nhiên, gia đình.
{id:'gau-danh-rang',title:'Gấu Con Đánh Răng',category:'Thói quen tốt',age:3,minutes:3,animal:'bear',friend:'bear',color:'#f1e4d2',tag:'Răng chắc khỏe',desc:'Ăn kẹo xong mà quên đánh răng thì sao nhỉ?',moral:'Bé đánh răng mỗi sáng và mỗi tối trước khi ngủ để răng luôn chắc khỏe, trắng sáng.',scenes:[['Mật ong ngọt lịm','Gấu Con rất thích ăn mật ong và kẹo ngọt. Tối nay ăn xong, Gấu Con ngáp một cái thật to rồi định đi ngủ luôn, không đánh răng.'],['Răng bị đau','Sáng hôm sau, Gấu Con ôm má kêu: Ôi, răng con đau quá! Gấu Mẹ xem rồi nói: Những con sâu răng tí hon đã đến ăn vụn kẹo trên răng con đấy.'],['Học đánh răng','Gấu Mẹ đưa cho Gấu Con một chiếc bàn chải nhỏ. Chải mặt trước, chải mặt trong, chải cả mặt nhai, nhẹ nhàng lên xuống. Rồi súc miệng thật sạch nào!'],['Nụ cười trắng sáng','Từ đó, sáng ngủ dậy và tối trước khi đi ngủ, Gấu Con đều tự đánh răng. Hàm răng của Gấu trắng sáng, Gấu cười thật tươi với cả nhà.']],quiz:[['Gấu Con thích ăn gì?',['Mật ong và kẹo','Cà rốt','Cỏ non'],0],['Vì sao răng Gấu Con bị đau?',['Vì bị ngã','Vì không đánh răng','Vì trời lạnh'],1],['Khi nào bé nên đánh răng?',['Buổi sáng và buổi tối','Một tuần một lần','Không cần đánh'],0]]},
{id:'tho-qua-duong',title:'Thỏ Con Qua Đường',category:'Kỹ năng sống',age:3,minutes:3,animal:'rabbit',friend:'rabbit',color:'#e4ecf2',tag:'An toàn giao thông',desc:'Đèn đỏ dừng lại, đèn xanh được đi!',moral:'Khi qua đường, bé luôn nắm tay người lớn, đi trên vạch kẻ đường và nhớ: đèn đỏ dừng lại, đèn xanh được đi.',scenes:[['Đi chợ cùng mẹ','Thỏ Con cùng mẹ đi chợ. Đến ngã tư, xe cộ chạy qua lại tấp nập. Thỏ Con định chạy ngay sang đường thì mẹ vội nắm tay con lại.'],['Đèn đỏ dừng lại','Mẹ chỉ lên cột đèn: Đèn đỏ là phải dừng lại con nhé. Lúc này xe đang chạy, mình đứng chờ trên vỉa hè cho an toàn.'],['Đèn xanh được đi','Đèn chuyển sang màu xanh. Mẹ dạy Thỏ Con nhìn bên trái, nhìn bên phải, rồi nắm tay mẹ đi trên vạch kẻ trắng.'],['Bé nhớ bài học','Sang đến bên kia đường, Thỏ Con đọc vang: Đèn đỏ dừng lại, đèn xanh được đi, qua đường nắm tay người lớn! Mẹ khen Thỏ Con thật ngoan.']],quiz:[['Đèn màu gì thì phải dừng lại?',['Đèn đỏ','Đèn xanh','Đèn tím'],0],['Khi qua đường, bé đi ở đâu?',['Giữa đường','Trên vạch kẻ trắng','Chạy thật nhanh'],1],['Qua đường bé cần làm gì?',['Nắm tay người lớn','Đi một mình','Vừa đi vừa chơi'],0]]},
{id:'nam-vit-con',title:'Năm Chú Vịt Con',category:'Học đếm & màu sắc',age:3,minutes:3,animal:'duck',friend:'duck',color:'#dcecef',tag:'Đếm từ 1 đến 5',desc:'Cùng Vịt Mẹ đếm xem có đủ năm chú vịt con không nhé!',moral:'Bé tập đếm từ một đến năm cùng các chú vịt. Đi đâu bé cũng nhớ ở gần bố mẹ và trả lời ngay khi bố mẹ gọi nhé.',scenes:[['Năm chú vịt con','Vịt Mẹ có năm chú vịt con. Một, hai, ba, bốn, năm! Sáng nào cả nhà cũng lạch bạch đi bơi ở cái ao xanh sau đồi.'],['Bốn, rồi ba','Vịt Mẹ gọi: Cạp cạp cạp! Nhưng chỉ có bốn chú vịt con bơi về. Mẹ gọi lần nữa, chỉ còn thấy ba chú. Vịt Mẹ lo lắng lắm.'],['Mẹ đi tìm con','Vịt Mẹ đi tìm khắp nơi. Hóa ra các chú vịt con mải chơi trốn tìm sau đám lau sậy. Một chú, rồi hai chú lần lượt ló đầu ra cười khúc khích.'],['Đủ năm chú rồi','Vịt Mẹ gọi thật to: Cạp cạp cạp! Thế là cả năm chú vịt con cùng bơi về bên mẹ. Mình cùng đếm nhé: một, hai, ba, bốn, năm! Cả nhà vui quá!']],quiz:[['Vịt Mẹ có mấy chú vịt con?',['Ba chú','Năm chú','Mười chú'],1],['Các chú vịt con trốn ở đâu?',['Sau đám lau sậy','Trên cây cao','Trong nhà'],0],['Khi bố mẹ gọi, bé làm gì?',['Trốn đi','Trả lời và đi về','Không nghe'],1]]},
{id:'cau-vong',title:'Cầu Vồng Của Gà Con',category:'Học đếm & màu sắc',age:3,minutes:3,animal:'chick',friend:'hen',color:'#eaf0f8',tag:'Học màu sắc',desc:'Sau cơn mưa, Gà Con học tên bảy màu cầu vồng.',moral:'Thế giới quanh bé có thật nhiều màu sắc. Bé hãy tập gọi tên màu của những đồ vật quanh mình nhé.',scenes:[['Cơn mưa rào','Trời đổ mưa rào. Gà Con đứng trú dưới chiếc lá to, nhìn những hạt mưa rơi tí tách. Gà Con hỏi: Bao giờ mưa mới tạnh hả mẹ?'],['Mặt trời ló ra','Một lát sau, mưa tạnh. Ông Mặt Trời ló ra, cười thật tươi. Trên bầu trời hiện ra một chiếc cầu vồng thật đẹp.'],['Bảy màu cầu vồng','Gà Mẹ chỉ cho Gà Con: Đây là màu đỏ, màu cam, màu vàng, màu xanh lá, màu xanh dương, màu chàm và màu tím. Cầu vồng có bảy màu con ạ!'],['Tìm màu quanh em','Gà Con chạy đi tìm: Bông hoa màu đỏ, quả cam màu cam, ông mặt trời màu vàng, chiếc lá màu xanh lá! Gà Con vui sướng vì đã biết thật nhiều màu.']],quiz:[['Cầu vồng có mấy màu?',['Ba màu','Bảy màu','Hai màu'],1],['Chiếc lá cây thường có màu gì?',['Màu xanh lá','Màu tím','Màu đen'],0],['Cầu vồng hiện ra khi nào?',['Sau cơn mưa, khi có nắng','Lúc nửa đêm','Khi có tuyết'],0]]},
{id:'meo-treo-cau',title:'Con Mèo Mà Trèo Cây Cau',category:'Đồng dao & thơ',age:3,minutes:2,animal:'cat',friend:'mouse',color:'#eef0d8',tag:'Đồng dao dân gian',desc:'Bài đồng dao ông bà vẫn đọc, bé vỗ tay đọc theo nhé!',moral:'Đồng dao là những câu hát vui ông bà để lại. Bé vừa đọc vừa vỗ tay theo nhịp để nhớ thật lâu nhé.',scenes:[['Cây cau cao vút','Ngày xưa, ông bà mình hay đọc cho các bé nghe bài đồng dao này. Mình cùng đọc nhé. Con mèo mà trèo cây cau.'],['Mèo hỏi thăm','Hỏi thăm chú chuột đi đâu vắng nhà. Mèo ngó nghiêng tìm mãi mà chẳng thấy chú Chuột đâu cả.'],['Chuột đi chợ xa','Chú chuột đi chợ đường xa. Mua mắm mua muối giỗ cha con mèo. Chuột nhanh trí đi vắng rồi, Mèo ơi là Mèo!'],['Cùng đọc lại nào','Bé vỗ tay đọc lại cùng mẹ nhé. Con mèo mà trèo cây cau, hỏi thăm chú chuột đi đâu vắng nhà. Chú chuột đi chợ đường xa, mua mắm mua muối giỗ cha con mèo.']],quiz:[['Con mèo trèo lên cây gì?',['Cây cau','Cây dừa','Cây chuối'],0],['Mèo hỏi thăm ai?',['Chú Chó','Chú Chuột','Chú Gà'],1],['Chú chuột đi đâu?',['Đi chợ đường xa','Đi ngủ','Đi học'],0]]},
{id:'dan-ga-con',title:'Bài Thơ Đàn Gà Con',category:'Đồng dao & thơ',age:3,minutes:2,animal:'chick',friend:'hen',color:'#f6efd2',tag:'Thơ cho bé',desc:'Bài thơ vui về đàn gà con lông vàng óng.',moral:'Đàn gà con biết nghe lời mẹ và chia nhau thức ăn. Bé đọc thơ theo nhịp, vừa đọc vừa làm động tác gà con nhé.',scenes:[['Gà mẹ gọi đàn','Cục ta cục tác, gà mẹ gọi đàn. Lông vàng óng ánh, gà con chạy sang.'],['Đi tìm thóc','Chiếp chiếp chiếp chiếp, bới đất tìm sâu. Hạt thóc hạt ngô, chia nhau cùng ăn.'],['Trời đổ mưa','Mây đen kéo tới, mưa rơi lộp độp. Gà con nhanh chân, chui vào cánh mẹ.'],['Ngủ ngoan nhé','Mưa tạnh nắng lên, gà con lớn nhanh. Ngoan ngoan ngủ nhé, trong cánh mẹ hiền.']],quiz:[['Lông gà con màu gì?',['Màu vàng','Màu đen','Màu xanh'],0],['Gà con chia nhau ăn gì?',['Thóc và ngô','Kem lạnh','Bánh kẹo'],0],['Khi trời mưa, gà con trốn ở đâu?',['Dưới cánh mẹ','Trên cây','Dưới ao'],0]]},
{id:'soc-mua-thu',title:'Bạn Sóc và Mùa Thu',category:'Thiên nhiên',age:3,minutes:3,animal:'squirrel',friend:'mouse',color:'#f4e3cc',tag:'Các mùa trong năm',desc:'Lá vàng rơi, Sóc nhặt hạt dẻ chuẩn bị cho mùa đông.',moral:'Mỗi mùa có một vẻ đẹp riêng. Biết chuẩn bị trước và giúp đỡ bạn bè sẽ giúp mình vượt qua những ngày khó khăn.',scenes:[['Lá vàng rơi','Mùa thu đến, lá cây chuyển sang màu vàng, màu đỏ rồi rơi xào xạc. Gió thổi nhè nhẹ. Bạn Sóc biết mùa đông lạnh giá sắp đến rồi.'],['Nhặt hạt dẻ','Sóc chạy nhảy khắp rừng, nhặt từng hạt dẻ, hạt thông. Sóc nói: Mình phải để dành thức ăn cho mùa đông, khi tuyết phủ trắng rừng.'],['Giúp bạn Chuột','Trên đường về, Sóc gặp Chuột đang loay hoay vì túi hạt bị rách. Sóc vội lấy dây leo buộc lại giúp bạn. Hai bạn cùng khiêng hạt về nhà.'],['Mùa đông ấm áp','Mùa đông đến, tuyết rơi trắng xóa. Trong tổ ấm, Sóc và Chuột cùng ăn hạt dẻ, nghe tiếng gió ngoài kia. Thật ấm áp biết bao!']],quiz:[['Mùa thu, lá cây có màu gì?',['Vàng và đỏ','Màu tím','Màu đen'],0],['Sóc nhặt hạt để làm gì?',['Để dành cho mùa đông','Để ném chơi','Để vứt đi'],0],['Sóc đã giúp ai?',['Bạn Chuột','Bạn Cáo','Bạn Vịt'],0]]},
{id:'qua-tang-me',title:'Món Quà Tặng Mẹ',category:'Gia đình',age:3,minutes:3,animal:'rabbit',friend:'rabbit',color:'#f6e2e6',tag:'Yêu thương mẹ',desc:'Không có tiền mua quà, Thỏ Con làm gì tặng mẹ?',moral:'Món quà quý nhất là tấm lòng của bé. Một bông hoa, một tấm thiệp tự làm hay một cái ôm cũng làm bố mẹ thật hạnh phúc.',scenes:[['Sinh nhật của mẹ','Hôm nay là sinh nhật Thỏ Mẹ. Thỏ Con muốn tặng mẹ một món quà thật đặc biệt, nhưng Thỏ Con chẳng có tiền để mua quà.'],['Hái hoa trong vườn','Thỏ Con ra vườn hái những bông hoa đẹp nhất: hoa đỏ, hoa vàng, hoa tím. Thỏ Con buộc chúng thành một bó hoa xinh xắn.'],['Tấm thiệp tự làm','Về nhà, Thỏ Con lấy bút màu vẽ một tấm thiệp. Thỏ vẽ mẹ, vẽ con, vẽ một trái tim thật to và viết: Con yêu mẹ!'],['Món quà của con','Thỏ Con tặng mẹ bó hoa và tấm thiệp, rồi ôm mẹ thật chặt. Thỏ Mẹ xúc động: Đây là món quà đẹp nhất mẹ từng nhận. Mẹ yêu con nhiều lắm!']],quiz:[['Hôm nay là ngày gì của Thỏ Mẹ?',['Sinh nhật','Ngày đi chợ','Ngày đi học'],0],['Thỏ Con tặng mẹ những gì?',['Bó hoa và tấm thiệp','Một chiếc xe','Cái bánh mua sẵn'],0],['Món quà quý nhất là gì?',['Món quà đắt tiền','Tấm lòng yêu thương của bé','Không có quà'],1]]}
];
